import json


def describe_response(status, headers, body):
    lower = {name.lower(): value for name, value in headers.items()}
    families = {1: "informational", 2: "success", 3: "redirect", 4: "client error", 5: "server error"}
    content_type = lower.get("content-type", "").split(";", 1)[0].strip().lower()
    data = None
    if content_type == "application/json" and body:
        try:
            data = json.loads(body)
        except json.JSONDecodeError as e:
            raise ValueError(f"response body is not valid JSON: {e}") from e
    message = None
    if status >= 400:
        error = data.get("error") if isinstance(data, dict) else None
        text = error.get("message") if isinstance(error, dict) else None
        message = text if isinstance(text, str) else f"HTTP {status}"
    return {
        "family": families.get(status // 100),
        "retryable": status in (408, 429, 500, 502, 503, 504),
        "request_id": lower.get("x-request-id"),
        "data": data,
        "message": message,
    }

