@test("a successful JSON response")
def _():
    r = describe_response(200, {"Content-Type": "application/json; charset=utf-8", "X-Request-Id": "abc"}, '{"id": 7}')
    check_eq(r, {"family": "success", "retryable": False, "request_id": "abc", "data": {"id": 7}, "message": None})

@test("families")
def _():
    check_eq(describe_response(101, {}, "")["family"], "informational")
    check_eq(describe_response(204, {}, "")["family"], "success")
    check_eq(describe_response(304, {}, "")["family"], "redirect")
    check_eq(describe_response(404, {}, "")["family"], "client error")
    check_eq(describe_response(503, {}, "")["family"], "server error")

@test("what is worth retrying")
def _():
    for status in (408, 429, 500, 502, 503, 504):
        check(describe_response(status, {}, "")["retryable"], f"{status} should be retryable")
    for status in (200, 400, 401, 404, 409, 422, 501):
        check(not describe_response(status, {}, "")["retryable"], f"{status} should not be retryable")

@test("error messages")
def _():
    body = '{"error": {"code": "invalid_year", "message": "year must be between 0 and 2100"}}'
    r = describe_response(422, {"content-type": "Application/JSON"}, body)
    check_eq(r["message"], "year must be between 0 and 2100")
    check_eq(r["data"]["error"]["code"], "invalid_year")
    check_eq(describe_response(500, {"Content-Type": "text/html"}, "<h1>Oops</h1>")["message"], "HTTP 500")
    check_eq(describe_response(400, {"Content-Type": "application/json"}, '{"error": "bad"}')["message"], "HTTP 400")
    check_eq(describe_response(404, {"Content-Type": "application/json"}, "")["message"], "HTTP 404")
    check_eq(describe_response(409, {"Content-Type": "application/json"}, '{"error": {"message": 5}}')["message"], "HTTP 409")

@test("headers in any case, and non-JSON bodies")
def _():
    r = describe_response(201, {"x-REQUEST-id": "r1", "Content-Type": "text/plain"}, '{"id": 1}')
    check_eq(r["request_id"], "r1")
    check_eq(r["data"], None)
    check_eq(describe_response(200, {}, '{"id": 1}')["request_id"], None)
    check_eq(describe_response(200, {"Content-Type": "application/json"}, "[1, 2]")["data"], [1, 2])

@test("broken JSON is an error")
def _():
    check_raises(ValueError, describe_response, 200, {"Content-Type": "application/json"}, '{"id": ')

